/* Unlucky Tiger 39 by suda-code — https://uiverse.io/suda-code/unlucky-tiger-39 */
button {
  align-items: center;
  color: #ffffff;
  font-size: 18px;
  background: #58cc02;
  border: none !important;
  padding: 15px 16px;
  box-shadow: 0 4px 0 #58a700;
  border-radius: 12px;
  cursor: pointer;
}

button:active {
  box-shadow: none;
  transform: translate(0, 4px);
}
